import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa tutorials","description":"","frontmatter":{"title":"kiwa tutorials"},"headers":[],"relativePath":"tutorials/index.md","filePath":"tutorials/index.md"}'),d={name:"tutorials/index.md"};function i(s,e,c,n,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kiwa-tutorials" tabindex="-1">kiwa tutorials <a class="header-anchor" href="#kiwa-tutorials" aria-label="Permalink to &quot;kiwa tutorials&quot;">​</a></h1><p>Step-by-step tutorials that take a fresh reader from &quot;no kiwa installed&quot; to a runnable test in under 10 minutes. Each tutorial is self-contained — the code samples paste directly into an empty repo and pass.</p><h2 id="tutorial-index" tabindex="-1">Tutorial index <a class="header-anchor" href="#tutorial-index" aria-label="Permalink to &quot;Tutorial index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Tutorial</th><th>Runtime</th><th>Time</th></tr></thead><tbody><tr><td>1</td><td><a href="./01-supabase-auth-first-test">Your first Supabase Auth test in 5 min</a></td><td>Node.js / vitest</td><td>5 min</td></tr><tr><td>2</td><td><a href="./02-rabbitmq-dlx-recipe">RabbitMQ DLX test recipe</a></td><td>Node.js / vitest</td><td>8 min</td></tr><tr><td>3</td><td><a href="./03-rust-contract-from-zero">Rust contract test from zero</a></td><td>Rust / cargo</td><td>10 min</td></tr><tr><td>4</td><td><a href="./04-nextjs-server-actions">Testing Next.js Server Actions with @kiwa-test/nextjs</a></td><td>Node.js / vitest</td><td>6 min</td></tr><tr><td>5</td><td><a href="./05-multi-provider-auth">Multi-provider auth (NextAuth + Clerk + Auth0)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>6</td><td><a href="./06-anthropic-chatbot-streaming">Anthropic chatbot streaming + tool_use</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>7</td><td><a href="./07-openai-tool-agent">OpenAI tool-use agent (function calling + parallel)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>8</td><td><a href="./08-vercel-ai-rag">Vercel AI SDK + LangChain RAG pipeline</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>9</td><td><a href="./09-supabase-realtime-chat">Supabase Realtime chat + presence + typing debounce</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>10</td><td><a href="./10-ably-collab-cursor">Ably shared cursor + 60 fps throttle + history rewind</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>11</td><td><a href="./11-socketio-notification">Socket.io notification + reconnect + backpressure</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>12</td><td><a href="./12-payment">Payment webhook mock (Stripe / Paddle / Lemon Squeezy)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>13</td><td><a href="./13-search">Search mock (Meilisearch / Algolia / Typesense)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>14</td><td><a href="./14-observability">Telemetry mock (OpenTelemetry / Datadog / Sentry)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>15</td><td><a href="./15-go-iris-chi">kiwa-test-go v0.5 Iris + Chi</a></td><td>Go / go test</td><td>10 min</td></tr><tr><td>16</td><td><a href="./16-multimodal-chat">Multimodal chat (image + audio + Whisper)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>17</td><td><a href="./17-mcp-tool-agent">MCP tool-use agent (JSON-RPC 2.0 chain)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>18</td><td><a href="./18-agent-orchestration">Agent orchestration (LangGraph + Assistants v2)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>19</td><td><a href="./19-storybook-design-system">Storybook 8 design system</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>20</td><td><a href="./20-playwright-ct">Playwright CT for 5 form patterns</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>21</td><td><a href="./21-visual-regression">Visual regression baseline / diff / accept</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>22</td><td><a href="./22-observability-dashboard">Observability dashboard (panel + refresh + badge)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>23</td><td><a href="./23-alert-orchestrator">Alert orchestrator (rule + route + silence + escalation)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>24</td><td><a href="./24-trace-flame-graph">Trace flame graph (span tree + drill-down + log correlation)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>25</td><td><a href="./25-reth-node-test">Reth node test (dev chain + reorg + fidelity matrix)</a></td><td>Rust / cargo</td><td>10 min</td></tr><tr><td>26</td><td><a href="./26-foundry-invariant-fuzz">Foundry invariant + fuzz runner (10 000 runs + shrink parser)</a></td><td>Rust / cargo</td><td>12 min</td></tr><tr><td>27</td><td><a href="./27-dapp-e2e-reorg">dApp e2e reorg (snapshot + revert + refetch across 4 scenarios)</a></td><td>Node.js / Playwright</td><td>12 min</td></tr><tr><td>28</td><td><a href="./28-solidjs-signal-app">SolidJS Signal + Effect + Resource + Suspense (fine-grained reactivity)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>29</td><td><a href="./29-fresh-islands">Fresh Islands + Route Handler + Head normalize (Deno partial hydration)</a></td><td>Node.js / vitest</td><td>10 min</td></tr><tr><td>30</td><td><a href="./30-hono-workers-rpc">HonoJS + hc RPC type-safe client + Workers env (KV / D1 / R2)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>31</td><td><a href="./31-kafka-event-pipeline">Kafka event pipeline (producer + consumer group + exactly-once + DLQ)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>32</td><td><a href="./32-redpanda-schema-registry">Redpanda + schema registry (Avro schemas + evolution + compatibility)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>33</td><td><a href="./33-nats-jetstream">NATS JetStream (persistent streams + KV + Object store + subject routing)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>34</td><td><a href="./34-webauthn-passkey">WebAuthn L3 + Passkey (virtual authenticator + attestation + sync fabric)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>35</td><td><a href="./35-oauth21-provider">OAuth 2.1 provider (PKCE + DPoP + refresh rotation + revocation)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>36</td><td><a href="./36-oidc-federation">OIDC provider + Federation (Discovery + DCR + id_token + trust chain)</a></td><td>Node.js / vitest</td><td>12 min</td></tr><tr><td>37</td><td><a href="./37-real-driver-testing">Real driver testing (Keycloak + oauth2-mock-server testcontainers)</a></td><td>Node.js / vitest + Docker</td><td>15 min</td></tr><tr><td>38</td><td><a href="./38-passkey-cable-flow">Passkey caBLE hybrid transport (QR + BLE + WebSocket tunnel)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>39</td><td><a href="./39-stripe-billing">Stripe advanced billing (subscription + 3DS + dunning)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>40</td><td><a href="./40-paddle-merchant">Paddle merchant-of-record (inline checkout + tier + VAT/GST auto-calc)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>41</td><td><a href="./41-lemon-squeezy-license">Lemon Squeezy refund + chargeback dispute lifecycle</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>42</td><td><a href="./42-cloudflare-durable-object">Cloudflare Workers Durable Object (realtime chat + Hibernation + storage)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>43</td><td><a href="./43-vercel-edge-streaming">Vercel Edge streaming (Next.js 15 middleware + geo routing + SSE backpressure)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>44</td><td><a href="./44-deno-deploy-geo">Deno Deploy geo (Deno KV + read-your-writes + Cron trigger)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>45</td><td><a href="./45-perf-harness-baseline">Perf-harness baseline (p95 baseline + regression detection walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>46</td><td><a href="./46-perf-baseline-migration">Perf baseline migration (3 package → 33 package transfer methodology)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>47</td><td><a href="./47-postgres-cdc-outbox">Postgres CDC + outbox pattern (change data capture walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>48</td><td><a href="./48-mysql-rls-tenant">MySQL RLS + multi-tenant (row-level security walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>49</td><td><a href="./49-vector-search-pgvector">pgvector + hybrid search (semantic + keyword retrieval walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>50</td><td><a href="./50-mutation-testing-baseline">Mutation testing baseline (Stryker + kill-rate baseline + tier gate walkthrough)</a></td><td>Node.js / vitest + Stryker</td><td>15 min</td></tr><tr><td>51</td><td><a href="./51-mutation-baseline-migration">Mutation baseline migration (22 → 33 package sweep methodology)</a></td><td>Node.js / vitest + Stryker</td><td>15 min</td></tr><tr><td>52</td><td><a href="./52-webrtc-video-signaling">WebRTC video call (signaling + ICE + simulcast + ICE restart walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>53</td><td><a href="./53-webtransport-stream">WebTransport stream (uni / bi / Datagram / migration walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>54</td><td><a href="./54-http3-multiplex">HTTP/3 multiplex (stream priority + HPACK + 0-RTT walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>55</td><td><a href="./55-release-script-filter-ssot">Release script filter SSOT (systematic root cause pattern walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>56</td><td><a href="./56-a11y-baseline">A11y baseline (axe-core + WCAG 2.1 AA gate + 3-layer harness walkthrough)</a></td><td>Node.js / vitest + jsdom</td><td>15 min</td></tr><tr><td>57</td><td><a href="./57-a11y-baseline-migration">A11y baseline migration (0 → 34 package sweep methodology)</a></td><td>Node.js / vitest + jsdom</td><td>15 min</td></tr><tr><td>58</td><td><a href="./58-kafka-raw-protocol">Kafka raw protocol (KIP-98 idempotent + txn coordinator + fetch session + ISR walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>59</td><td><a href="./59-redpanda-schema-evolution">Redpanda schema evolution (BACKWARD / FORWARD / FULL + subject naming + references walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>60</td><td><a href="./60-nats-jetstream-durable">NATS JetStream durable consumer (ack_wait + max_deliver + backoff + quarantine walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>61</td><td><a href="./61-postgres-logical-replication-advanced">Postgres logical replication advanced (streaming + origin + two-safe + cascade walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>62</td><td><a href="./62-mysql-group-replication">MySQL group replication (member join + primary election + conflict detection + member leave walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>63</td><td><a href="./63-sqlite-wal-fts5">SQLite WAL + FTS5 (journal_mode + checkpoint + virtual table + tokenizer + BM25 rank walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>64</td><td><a href="./64-payment-orchestration">Payment orchestration (multi-provider routing + failover + retry ladder + circuit breaker walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>65</td><td><a href="./65-stripe-connect-marketplace">Stripe Connect marketplace (dispute + refund + webhook idempotency + DAC7 walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr><tr><td>66</td><td><a href="./66-paddle-billing-v2">Paddle Billing v2 (grace period + proration + coupon stacking + recovery + vault migration walkthrough)</a></td><td>Node.js / vitest</td><td>15 min</td></tr></tbody></table><h2 id="ai-llm-tutorials-v1-12" tabindex="-1">AI-LLM tutorials (v1.12) <a class="header-anchor" href="#ai-llm-tutorials-v1-12" aria-label="Permalink to &quot;AI-LLM tutorials (v1.12)&quot;">​</a></h2><p>Tutorials 06 – 08 exercise the <a href="https://github.com/cardene777/kiwa/blob/main/packages/ai-llm/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/ai-llm</code></a> harness — one for each of Anthropic Messages API, OpenAI Chat Completions, and Vercel AI SDK + LangChain. See <a href="./../concepts/ai-llm-testing"><code>docs/concepts/ai-llm-testing.md</code></a> for why AI-LLM providers need extra fidelity / cost / accuracy axes.</p><h2 id="realtime-tutorials-v1-13" tabindex="-1">Realtime tutorials (v1.13) <a class="header-anchor" href="#realtime-tutorials-v1-13" aria-label="Permalink to &quot;Realtime tutorials (v1.13)&quot;">​</a></h2><p>Tutorials 09 – 11 exercise the new <a href="https://github.com/cardene777/kiwa/blob/main/packages/realtime/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/realtime</code></a> harness — one for each of Supabase Realtime, Ably, and Socket.io / SSE (Pusher shares the same engine but is not called out as a dedicated tutorial in v1.13). See <a href="./../concepts/realtime-testing"><code>docs/concepts/realtime-testing.md</code></a> for the 5 time-axis semantics (order / timing / drop / reconnect / backpressure) that realtime tests need beyond the request/response mocks of v1.11 + v1.12.</p><h2 id="component-test-tutorials-v1-16" tabindex="-1">Component test tutorials (v1.16) <a class="header-anchor" href="#component-test-tutorials-v1-16" aria-label="Permalink to &quot;Component test tutorials (v1.16)&quot;">​</a></h2><p>Tutorials 19 – 21 exercise the new <a href="https://github.com/cardene777/kiwa/blob/main/packages/component/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/component</code></a> harness — one for each of Storybook 8 (story registration + args + play + a11y), Playwright Component Testing (mount + interact + assert), and Chromatic (baseline / diff / accept / reject). See <a href="./../concepts/component-testing"><code>docs/concepts/component-testing.md</code></a> for the 3 surfaces + 6 semantic axes that component tests need beyond the request/response mocks of v1.11 + v1.12 + v1.13.</p><h2 id="observability-v2-tutorials-v1-17" tabindex="-1">Observability v2 tutorials (v1.17) <a class="header-anchor" href="#observability-v2-tutorials-v1-17" aria-label="Permalink to &quot;Observability v2 tutorials (v1.17)&quot;">​</a></h2><p>Tutorials 22 – 24 exercise the v2.0 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/observability/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/observability</code></a> — one for each of Grafana-style dashboards (panel refresh + threshold badge), Prometheus AlertManager (rule / route / silence / escalation lifecycle), and Jaeger flame graphs (span tree + drill-down + log correlation). See <a href="./../concepts/observability-v2-testing"><code>docs/concepts/observability-v2-testing.md</code></a> for the 4 axes v2 adds on top of the v1.1 <code>TelemetryCollector</code> and where the fidelity harness fits in.</p><h2 id="blockchain-深化-tutorials-v1-18" tabindex="-1">Blockchain 深化 tutorials (v1.18) <a class="header-anchor" href="#blockchain-深化-tutorials-v1-18" aria-label="Permalink to &quot;Blockchain 深化 tutorials (v1.18)&quot;">​</a></h2><p>Tutorials 25 – 27 exercise the v0.5 additions to <a href="https://github.com/cardene777/kiwa/blob/main/kiwa-rs/README.md" target="_blank" rel="noreferrer"><code>kiwa-test-rs</code></a> and the reorg helpers in <a href="https://github.com/cardene777/kiwa/blob/main/packages/dapp/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/dapp</code></a> — one for each of Reth NodeBuilder dev chain integration (<code>RethNode::spawn_dev</code> + <code>reth_reorg</code> + 7-row fidelity matrix), Foundry invariant + fuzz runner (10 000 runs with deterministic seed and shrink parser), and Playwright dApp reorg regression (<code>snapshotChain</code> / <code>revertChain</code> across 4 scenarios). See <a href="./../concepts/blockchain-testing"><code>docs/concepts/blockchain-testing.md</code></a> for the 4 axes v1.18 adds on top of the v1.10 <code>contract::foundry</code> + <code>contract::alloy</code> base and where each axis lands in the release-gate fidelity ratio.</p><h2 id="framework-深化-tutorials-v1-19" tabindex="-1">Framework 深化 tutorials (v1.19) <a class="header-anchor" href="#framework-深化-tutorials-v1-19" aria-label="Permalink to &quot;Framework 深化 tutorials (v1.19)&quot;">​</a></h2><p>Tutorials 28 – 30 exercise the three new modern web framework adapters — <a href="https://github.com/cardene777/kiwa/blob/main/packages/solidjs/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/solidjs</code></a>, <a href="https://github.com/cardene777/kiwa/blob/main/packages/fresh/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/fresh</code></a>, and <a href="https://github.com/cardene777/kiwa/blob/main/packages/hono/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/hono</code></a>. Each cuts down to a single vitest suite that walks the framework&#39;s characteristic runtime contract without booting the real runtime — SolidJS Signal-based fine-grained reactivity + Suspense-shaped resources (<code>mockSignal</code> / <code>mockEffect</code> / <code>batch</code> / <code>createResourceStub</code> / <code>renderWithSuspense</code>), Deno Fresh Islands architecture + Route Handler + Head normalize (<code>invokeFreshHandler</code> / <code>defineIsland</code> / <code>hydrateIslands</code> / <code>mergeHead</code>), and Cloudflare Workers-style HonoJS + hc typed RPC + KV / D1 / R2 mocks (<code>createHonoApp</code> / <code>createRpcClient</code> / <code>mockKVNamespace</code> / <code>mockD1Database</code> / <code>mockR2Bucket</code>). See <a href="./../concepts/modern-web-framework-testing"><code>docs/concepts/modern-web-framework-testing.md</code></a> for the 4 axes v1.19 adds on top of the v1.14 horizontal framework baseline.</p><h2 id="streaming-深化-tutorials-v1-20" tabindex="-1">Streaming 深化 tutorials (v1.20) <a class="header-anchor" href="#streaming-深化-tutorials-v1-20" aria-label="Permalink to &quot;Streaming 深化 tutorials (v1.20)&quot;">​</a></h2><p>Tutorials 31 – 33 exercise the new <a href="https://github.com/cardene777/kiwa/blob/main/packages/streaming/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/streaming</code></a> unified mock — one for each of Kafka (kafkajs-shaped producer / consumer group / transactional producer / DLQ), Redpanda (Kafka API compat + colocated schema registry with BACKWARD / FORWARD / FULL compatibility gates), and NATS JetStream (persistent streams + KV Store + Object Store + subject-based routing with <code>*</code> single-token and <code>&gt;</code> trailing-multi-token wildcards). See <a href="./../concepts/streaming-testing"><code>docs/concepts/streaming-testing.md</code></a> for the 5 semantics (producer / consumer / exactly-once / DLQ / schema-registry) that streaming tests need beyond the time-axis mocks of v1.13.</p><h2 id="auth-深化-tutorials-v1-21" tabindex="-1">Auth 深化 tutorials (v1.21) <a class="header-anchor" href="#auth-深化-tutorials-v1-21" aria-label="Permalink to &quot;Auth 深化 tutorials (v1.21)&quot;">​</a></h2><p>Tutorials 34 – 36 exercise the four new protocol adapters in <a href="https://github.com/cardene777/kiwa/blob/main/packages/auth/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/auth</code></a> — <code>setupWebAuthnEnv</code> (WebAuthn L3 virtual authenticator + attestation), <code>setupPasskeyEnv</code> (Passkey sync fabric backup + restore), <code>setupOAuth21Env</code> (OAuth 2.1 mock AS with PKCE + DPoP + refresh rotation + revocation), and <code>setupOidcEnv</code> (OIDC mock OP with Discovery + DCR + <code>id_token</code> sign / verify + JWKS rotation + OpenID Federation trust-chain resolution). See <a href="./../concepts/auth-protocol-testing"><code>docs/concepts/auth-protocol-testing.md</code></a> for the 4 axes (virtual authenticator / PKCE+DPoP / id_token / discovery+federation) that interactive auth tests need beyond the session-shaped mocks of v1.10-2.</p><h2 id="real-driver-tutorials-v1-22" tabindex="-1">Real driver tutorials (v1.22) <a class="header-anchor" href="#real-driver-tutorials-v1-22" aria-label="Permalink to &quot;Real driver tutorials (v1.22)&quot;">​</a></h2><p>Tutorials 37 – 38 exercise the v1.22 real driver layer on top of the v1.21 4 protocol mocks — Keycloak testcontainers wiring for OIDC + Federation, oauth2-mock-server testcontainers for OAuth 2.1, Chrome caBLE hybrid transport for Passkey. Tutorial 37 walks the 3 execution modes (<code>mock only</code> / <code>real-optional</code> / <code>real-required</code>) end-to-end with a Keycloak container; tutorial 38 walks the CTAP2 hybrid transport 5-axis fidelity harness (QR generation / BLE advertisement handshake / WebSocket tunnel establishment / credential migration payload / signature roundtrip). See <a href="./../concepts/real-driver-testing"><code>docs/concepts/real-driver-testing.md</code></a> for the 3 execution modes SSOT + the fidelity axis catalog across all 3 v1.22 dogfood apps.</p><h2 id="payment-深化-tutorials-v1-23" tabindex="-1">Payment 深化 tutorials (v1.23) <a class="header-anchor" href="#payment-深化-tutorials-v1-23" aria-label="Permalink to &quot;Payment 深化 tutorials (v1.23)&quot;">​</a></h2><p>Tutorials 39 – 41 exercise the v0.3 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/payment/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/payment</code></a> — 9 axes of advanced billing semantics (dunning / retry / 3DS v2 / SCA / PSD2 mandate / subscription lifecycle / invoice lifecycle / VAT-GST-sales-tax / chargeback dispute) — one for each of the 3 target providers Stripe (Next.js 15 subscription + 3DS + Smart Retries dunning), Paddle (Nuxt 3 merchant-of-record + inline checkout + tier upgrade + VAT/GST auto-calc), and Lemon Squeezy (SvelteKit hosted checkout + license key + refund + chargeback dispute). See <a href="./../concepts/billing-semantics"><code>docs/concepts/billing-semantics.md</code></a> for the 9-axis SSOT + provider-specific fidelity surface reference across all 3 v1.23 dogfood merchant apps.</p><h2 id="edge-serverless-深化-tutorials-v1-24" tabindex="-1">Edge/Serverless 深化 tutorials (v1.24) <a class="header-anchor" href="#edge-serverless-深化-tutorials-v1-24" aria-label="Permalink to &quot;Edge/Serverless 深化 tutorials (v1.24)&quot;">​</a></h2><p>Tutorials 42 – 44 exercise the v0.2 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/edge/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/edge</code></a> — 8 axes of advanced edge semantics (Durable Object / WebSocket edge / edge KV / geo-replicated / Cron trigger / subrequest limit / CPU time limit / streaming Response) — one for each of the 3 target platforms Cloudflare Workers (realtime chat via Durable Objects + Hibernation API + storage transactional + WebSocket edge broadcast), Vercel Edge (Next.js 15 middleware + geo routing + edge KV cache invalidation + SSE streaming with backpressure), and Deno Deploy (Fresh + multi-region Deno KV write + read-your-writes consistency + Deno Deploy Cron + queue trigger). See <a href="./../concepts/edge-runtime-testing"><code>docs/concepts/edge-runtime-testing.md</code></a> for the 8-axis SSOT + platform-specific fidelity surface reference across all 3 v1.24 dogfood edge apps.</p><h2 id="perf-harness-sweep-tutorials-v1-25" tabindex="-1">Perf-harness sweep tutorials (v1.25) <a class="header-anchor" href="#perf-harness-sweep-tutorials-v1-25" aria-label="Permalink to &quot;Perf-harness sweep tutorials (v1.25)&quot;">​</a></h2><p>Tutorials 45 – 46 exercise the v0.2 rollout of <a href="https://github.com/cardene777/kiwa/blob/main/packages/perf-harness/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/perf-harness</code></a> — the p50 / p95 / p99 measurement + baseline persistence + regression detection primitives from v1.13-1 now applied to every kiwa package (33 total). Tutorial 45 walks the primitive stack (<code>measure</code> + <code>saveBaseline</code> + <code>loadBaseline</code> + <code>detectRegression</code> + <code>evaluatePerfGate</code>) against a trivial pure function so the numbers are easy to reason about; tutorial 46 documents the 6-step migration recipe used across the v1.25-1 through v1.25-4 sub-milestones to add a perf suite to any new package in under 15 minutes. See <a href="./../concepts/perf-testing-ssot"><code>docs/concepts/perf-testing-ssot.md</code></a> for the p50 / p95 / p99 SSOT + 3-layer harness rules (3 warmup + 100 iteration + 20 % threshold) + the 33 package coverage grid across core / framework adapter / test type / SaaS layer.</p><h2 id="database-深化-tutorials-v1-26" tabindex="-1">Database 深化 tutorials (v1.26) <a class="header-anchor" href="#database-深化-tutorials-v1-26" aria-label="Permalink to &quot;Database 深化 tutorials (v1.26)&quot;">​</a></h2><p>Tutorials 47 – 49 exercise the v0.9 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/orm/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/orm</code></a> — 8 axes of advanced db semantics (replication / CDC / logical replication / MVCC / RLS / connection pool / partitioning / vector store) layered on top of the v0.8 <code>setupOrmEnv</code> — one for each of the 3 target dogfood app combinations Postgres CDC + outbox (Next.js 15 + drizzle + Postgres 16 logical replication + Debezium-style outbox + Redis Streams consumer), MySQL RLS + multi-tenant (Nuxt 3 + Prisma + MySQL 8 row-level security policy + tenant isolation + audit log), and pgvector + hybrid search (SvelteKit + kysely + Postgres 16 + pgvector IVFFlat / HNSW + hybrid ranking). See <a href="./../concepts/db-advanced-testing"><code>docs/concepts/db-advanced-testing.md</code></a> for the 8-axis SSOT + provider × backend fidelity table + 3 × 3 × 8 = 72 row coverage grid across all 3 v1.26 dogfood db apps.</p><h2 id="mutation-testing-sweep-tutorials-v1-27" tabindex="-1">Mutation testing sweep tutorials (v1.27) <a class="header-anchor" href="#mutation-testing-sweep-tutorials-v1-27" aria-label="Permalink to &quot;Mutation testing sweep tutorials (v1.27)&quot;">​</a></h2><p>Tutorials 50 – 51 exercise the v0.3 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/quality-metrics/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/quality-metrics</code></a> — the 4-tier mutation SSOT (<code>DEFAULT_MUTATION_TIER_THRESHOLDS</code> + <code>resolveMutationTier</code> + <code>assertMutationTier</code>) + 12-axis release gate (<code>evaluateReleaseGate({ mutationTier })</code>) — layered on top of the v0.2 7 / 11-axis release gate — now applied to every kiwa package across the 4 layers Core / Framework / SaaS / Test type. Tutorial 50 walks the primitive stack (Stryker <code>stryker.config.mjs</code> + baseline JSON persistence + <code>assertMutationTier</code> + <code>evaluateReleaseGate</code> 12-axis path) against a trivial pure function so the mutants are easy to reason about; tutorial 51 documents the 6-step migration recipe used across the v1.27-1 through v1.27-3 sub-milestones to add a mutation baseline + tier gate to any new package in under 15 minutes. See <a href="./../concepts/mutation-testing-ssot"><code>docs/concepts/mutation-testing-ssot.md</code></a> for the kill rate + 4-tier threshold SSOT + baseline persistence + 12-axis release gate integration + 3-layer harness alignment across the 33 package coverage grid.</p><h2 id="advanced-realtime-transport-tutorials-v1-28" tabindex="-1">Advanced realtime transport tutorials (v1.28) <a class="header-anchor" href="#advanced-realtime-transport-tutorials-v1-28" aria-label="Permalink to &quot;Advanced realtime transport tutorials (v1.28)&quot;">​</a></h2><p>Tutorials 52 – 54 exercise the v0.2 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/realtime/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/realtime</code></a> — 3 protocol × 8 axis low-layer transport mocks (<code>createWebRtcSignalingMock</code> + <code>createWebRtcIceMock</code> + <code>createWebRtcTrackMock</code> + <code>createWebRtcDataChannelMock</code> + <code>createWebTransportUniMock</code> + <code>createWebTransportBiMock</code> + <code>createHttp3PushMock</code> + <code>createQuicMultiplexMock</code>) + 24-row <code>SEMANTICS_GRID</code> + <code>measureSemanticsAxis</code> / <code>measureSemanticsGrid</code> fidelity harness + <code>resolveRealtimeDriver</code> env-gate — layered on top of the v0.1 5 time-axis semantics — now exercised through 3 dogfood apps (Next.js 15 + mediasoup WebRTC video call / Nuxt 3 + aioquic WebTransport stream room / SvelteKit + nginx-quic HTTP/3 QUIC multiplex). Tutorial 52 walks the WebRTC video call adapter (<code>VideoCallAdapter</code> — 8 ops covering signaling / ICE / track / simulcast / ICE restart, seed-offset per peer to preserve mediasoup&#39;s unique-fingerprint invariant); tutorial 53 walks the WebTransport stream adapter (<code>WebTransportStreamAdapter</code> — 9 ops covering uni / bi / backpressure / reset / Datagram / connection migration, per-stream flow-control window semantics); tutorial 54 walks the HTTP/3 multiplex adapter (<code>Http3MultiplexAdapter</code> — 9 ops covering priority-scheduled concurrent streams / HPACK dynamic table / 0-RTT anti-replay refusal / FIN on closeStream). See <a href="./../concepts/webrtc-webtransport-testing"><code>docs/concepts/webrtc-webtransport-testing.md</code></a> for the 8-axis SSOT + 24-row grid + protocol × framework fidelity table + P2P vs SFU selection guide + ICE trickle vs half-trickle + WebTransport vs WebSocket differences reference across all 3 v1.28 dogfood realtime apps.</p><h2 id="release-invariants-tutorials-v1-29" tabindex="-1">Release invariants tutorials (v1.29) <a class="header-anchor" href="#release-invariants-tutorials-v1-29" aria-label="Permalink to &quot;Release invariants tutorials (v1.29)&quot;">​</a></h2><p>Tutorial 55 exercises the v0.1 release of <a href="https://github.com/cardene777/kiwa/blob/main/packages/release-invariants/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/release-invariants</code></a> — 3 pure invariant checkers (<code>checkReleaseScriptFilter</code> + <code>checkProvenanceFlagAbsence</code> + <code>checkGateScriptPackageCoverage</code>) + 1-shot <code>buildReleaseInvariantsSummary</code> aggregator — the systematic root cause pattern SSOT that turned a 4-time recurring release script filter bug into a first-class fail-fast release-smoke axis. Tutorial 55 walks the provider-neutral <code>ReleaseInvariantsAdapter</code> contract with a mock adapter + a file adapter, plus 4 RED / GREEN behavior tests that pin the exact failure modes v1.14 payment / v1.25 perf-harness / v1.27 quality-metrics / v1.28 realtime all rediscovered. See <a href="./../concepts/release-invariants"><code>docs/concepts/release-invariants.md</code></a> for the 3-invariant SSOT + systematic root cause pattern + 4-time rediscovery ledger + 7-milestone snippet validation streak reference.</p><h2 id="a11y-sweep-tutorials-v1-30" tabindex="-1">A11y sweep tutorials (v1.30) <a class="header-anchor" href="#a11y-sweep-tutorials-v1-30" aria-label="Permalink to &quot;A11y sweep tutorials (v1.30)&quot;">​</a></h2><p>Tutorials 56 – 57 exercise the v1.1 rollout of <a href="https://github.com/cardene777/kiwa/blob/main/packages/a11y/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/a11y</code></a> — the v1.0 <code>runAxe</code> + <code>reportViolations</code> + <code>expectNoViolations</code> primitives from v1.16 now applied to every kiwa package (34 total), plus the new v1.1 3-layer harness (<code>runLayerHarness</code> + <code>bucketViolations</code> + <code>unionByRule</code> + <code>computeTotals</code> + <code>isHarnessOk</code> + <code>summariseHarness</code>) that unions jsdom + Playwright + SSR-hydration violations by rule id with provenance. Tutorial 56 walks the primitive stack (<code>runAxe</code> with WCAG 2.1 AA tag filter + <code>runLayerHarness</code> with jsdom fixture + <code>a11yFromBaseline</code> + <code>assertA11yTier</code> + <code>evaluateReleaseGate</code> 13-axis path) against a trivial labelled markup so the impact buckets are easy to reason about; tutorial 57 documents the 6-step migration recipe used across the v1.30-1 through v1.30-3 sub-milestones to add an a11y baseline + tier gate to any new package in under 15 minutes. See <a href="./../concepts/a11y-testing-ssot"><code>docs/concepts/a11y-testing-ssot.md</code></a> for the WCAG 2.1 AA SSOT + 4-tier threshold rationale + baseline persistence + 3-layer harness rules + jsdom vs Playwright vs SSR-hydration nuances across the 34 package coverage grid.</p><h2 id="streaming-深化-ii-tutorials-v1-31" tabindex="-1">Streaming 深化 II tutorials (v1.31) <a class="header-anchor" href="#streaming-深化-ii-tutorials-v1-31" aria-label="Permalink to &quot;Streaming 深化 II tutorials (v1.31)&quot;">​</a></h2><p>Tutorials 58 – 60 exercise the v0.3 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/streaming/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/streaming</code></a> — 8 advanced-semantics axes (<code>createKafkaRawProtocol</code> + <code>createKafkaConsumerGroup</code> + <code>createRedpandaSchemaEvolution</code> + <code>createRedpandaTransactions</code> + <code>createNatsJetStreamDurable</code> + <code>createNatsKvObject</code> + <code>createExactlyOnceSemantics</code> + <code>createConsumerLagTelemetry</code>) layered on top of the v0.1 5-semantic base + a <code>createFidelityHarness()</code> describing the 3 provider × 8 axis = 24 cell grid + a <code>KIWA_MODE=real</code> env-gate that lets the same assertions run against real Kafka 3.7 / Redpanda 23+ / NATS 2.10+ testcontainers. Tutorial 58 walks the Kafka raw protocol adapter (KIP-98 idempotent producer + transaction coordinator state machine + KIP-227 incremental fetch session + ISR + high-watermark advance rules); tutorial 59 walks the Redpanda schema evolution adapter (BACKWARD / FORWARD / FULL compatibility check with structural markers + 3 subject naming strategies + Confluent-shaped schema reference graph); tutorial 60 walks the NATS JetStream durable adapter (<code>durable_name</code> + <code>ack_wait</code> + <code>max_deliver</code> + <code>backoff[]</code> + <code>ack_policy</code> + quarantine on the <code>maxDeliver</code>+1st failure with explicit-clock <code>sweepExpired</code>). See <a href="./../concepts/streaming-real-driver-testing"><code>docs/concepts/streaming-real-driver-testing.md</code></a> for the 8-axis SSOT + 24-cell grid + testcontainers pattern + <code>KIWA_MODE=real</code> env-gate contract + <code>not-applicable</code> semantics reference across all 3 v1.31 dogfood streaming apps.</p><h2 id="database-深化-ii-tutorials-v1-32" tabindex="-1">Database 深化 II tutorials (v1.32) <a class="header-anchor" href="#database-深化-ii-tutorials-v1-32" aria-label="Permalink to &quot;Database 深化 II tutorials (v1.32)&quot;">​</a></h2><p>Tutorials 61 – 63 exercise the v0.10 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/orm/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/orm</code></a> — 8 advanced-semantics axes (<code>createLogicalReplicationAdvancedSession</code> + <code>createMvccAdvancedSession</code> + <code>createMysqlClusterSession</code> + <code>createBinlogSession</code> + <code>createSqliteWalSession</code> + <code>createFts5Session</code> + <code>createTxnIsolationSession</code> + <code>createPoolAdvancedSession</code>) layered on top of the v0.9 8-semantic base + a <code>collectFidelityCoverage()</code> describing the 3 provider × 3 backend × 16 axis = 144 cell grid + a <code>KIWA_MODE=real</code> env-gate that lets the same assertions run against real Postgres 16 / MySQL 8 / SQLite (libsql) testcontainers. Tutorial 61 walks the Postgres logical replication advanced adapter (pgoutput <code>START_REPLICATION</code> handshake + <code>pg_replication_origin_advance</code> progress tracking + <code>synchronous_commit = remote_apply</code> two-safe confirmation + cascaded subscription topology with self-loop guard); tutorial 62 walks the MySQL group replication adapter (<code>group_replication_member_weight</code> + single-primary election among joined members + certification conflict counter + <code>STOP GROUP_REPLICATION</code> primary-clearing); tutorial 63 walks the SQLite WAL + FTS5 adapters (<code>PRAGMA journal_mode = WAL</code> switch + <code>wal_autocheckpoint</code> size threshold + <code>PRAGMA wal_checkpoint(TRUNCATE)</code> + <code>-shm</code> wal-index mapping, plus <code>CREATE VIRTUAL TABLE ... USING fts5</code> + <code>unicode61</code> / <code>porter</code> / <code>trigram</code> tokenizers + <code>MATCH</code> queries with BM25 rank + <code>fts5vocab</code> term inspection). See <a href="./../concepts/database-real-driver-testing"><code>docs/concepts/database-real-driver-testing.md</code></a> for the 16-axis SSOT + 144-cell grid + testcontainers pattern + <code>KIWA_MODE=real</code> env-gate contract + backend-specific <code>_KEY</code> env mapping reference across all 3 v1.32 dogfood database apps.</p><h2 id="payment-深化-ii-tutorials-v1-33" tabindex="-1">Payment 深化 II tutorials (v1.33) <a class="header-anchor" href="#payment-深化-ii-tutorials-v1-33" aria-label="Permalink to &quot;Payment 深化 II tutorials (v1.33)&quot;">​</a></h2><p>Tutorials 64 – 66 exercise the v0.4 additions to <a href="https://github.com/cardene777/kiwa/blob/main/packages/payment/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/payment</code></a> — 8 advanced-semantics axes (<code>startOrchestration</code> + <code>startRecovery</code> + <code>startRefund</code> + <code>openDispute</code> + <code>startIdempotency</code> + <code>calculateLocalizedTax</code> + <code>startSubscriptionMachine</code> + <code>startVault</code>) layered on top of the v0.3 9-semantic base + a <code>collectFidelityCoverage()</code> describing the 3 provider × 17 axis grid (of which 24 cells belong to the v0.4 slice) + a <code>KIWA_MODE=real</code> env-gate (<code>resolveMode</code> / <code>resolveAllModes</code> / <code>assertMode</code>) that lets the same assertions run against real Stripe test mode + Paddle sandbox + Lemon Squeezy sandbox. Tutorial 64 walks the payment orchestration adapter (ordered provider list + <code>maxRetriesPerProvider</code> retry ladder + failover cascade + <code>circuitBreakerThreshold</code> + <code>probeCircuit</code> outage window); tutorial 65 walks the Stripe Connect marketplace surface (5-stage dispute lifecycle + partial refund with policy caps + webhook idempotency scoped by handler name + EU DAC7 report aggregation with reverse-charge B2B handling); tutorial 66 walks the Paddle Billing v2 subscription surface (grace period with recover / expire branches + mid-cycle proration arithmetic + coupon stacking with 100 % cap + 4-mechanism recovery ladder + cross-provider vault migration with PCI SAQ-A verification). See <a href="./../concepts/payment-real-driver-testing"><code>docs/concepts/payment-real-driver-testing.md</code></a> for the 8-axis SSOT + 24-cell grid + <code>KIWA_MODE=real</code> env-gate contract + provider-specific <code>_KEY</code> env mapping (<code>STRIPE_KEY</code> / <code>PADDLE_KEY</code> / <code>LEMONSQUEEZY_KEY</code>) reference across all 3 v1.33 dogfood payment apps.</p>',44)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
